import{WETLANDS_DATA}from"./wetlands-data.js";let activeTypeFilter="All",activeStateFilter="All",searchQuery="";function initTheme(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"🌙":"☀️"})}function initNavbar(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!n),t.classList.toggle("active")})}function renderStats(){const e=document.getElementById("stats-grid");e&&WETLANDS_DATA.stats&&(e.innerHTML=WETLANDS_DATA.stats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-value">${e.value}</div>\n            <div class="stat-label">${e.label}</div>\n        </div>\n    `).join(""))}function renderStateFilterOptions(){const e=document.getElementById("state-filter");e&&WETLANDS_DATA.states&&(e.innerHTML=WETLANDS_DATA.states.map(e=>`<option value="${e}">${e}</option>`).join(""))}function renderTypeFilterPills(){const e=document.getElementById("type-pills-row");e&&WETLANDS_DATA.types&&(e.innerHTML=WETLANDS_DATA.types.map(e=>`\n        <button class="type-pill-btn ${"All"===e?"active":""}" data-type="${e}">\n            ${e}\n        </button>\n    `).join(""))}function getFilteredWetlands(){return WETLANDS_DATA.wetlands.filter(e=>{const t="All"===activeTypeFilter||e.type===activeTypeFilter,n="All"===activeStateFilter||e.state===activeStateFilter,a=searchQuery.toLowerCase().trim(),s=!a||e.name.toLowerCase().includes(a)||e.state.toLowerCase().includes(a)||e.type.toLowerCase().includes(a)||e.shortDesc.toLowerCase().includes(a)||e.keyFauna&&e.keyFauna.some(e=>e.toLowerCase().includes(a));return t&&n&&s})}function renderFeaturedWetlands(){const e=document.getElementById("featured-grid");if(!e)return;const t=WETLANDS_DATA.wetlands.filter(e=>e.isFeatured);e.innerHTML=t.map(createWetlandCardHtml).join("")}function renderAllWetlands(){const e=document.getElementById("all-wetlands-grid"),t=document.getElementById("results-count-text");if(!e)return;const n=getFilteredWetlands();t&&(t.textContent=`Showing ${n.length} of ${WETLANDS_DATA.wetlands.length} wetlands`),0!==n.length?e.innerHTML=n.map(createWetlandCardHtml).join(""):e.innerHTML='<div style="grid-column: 1/-1; text-align: center; color: var(--wetland-text-sub); padding: 3rem;">No wetlands match your current filter and search query.</div>'}function createWetlandCardHtml(e){return`\n        <div class="wetland-card">\n            <div class="wetland-card-img">\n                <img src="${e.image}" alt="${e.name}" loading="lazy" />\n                <span class="wetland-type-badge">${e.type}</span>\n            </div>\n            <div class="wetland-card-body">\n                <div class="wetland-state-tag">📍 ${e.state}</div>\n                <h3 class="wetland-card-title">${e.name}</h3>\n                <p class="wetland-card-desc">${e.shortDesc}</p>\n                <div class="wetland-card-footer">\n                    <span class="wetland-area">Area: ${e.area}</span>\n                    <a href="${e.exploreUrl}" class="btn-explore">Explore</a>\n                </div>\n            </div>\n        </div>\n    `}function bindSearchAndFilters(){const e=document.getElementById("search-input"),t=document.getElementById("state-filter"),n=document.getElementById("type-pills-row");e&&e.addEventListener("input",e=>{searchQuery=e.target.value,renderAllWetlands()}),t&&t.addEventListener("change",e=>{activeStateFilter=e.target.value,renderAllWetlands()}),n&&n.addEventListener("click",e=>{e.target.classList.contains("type-pill-btn")&&(document.querySelectorAll(".type-pill-btn").forEach(e=>e.classList.remove("active")),e.target.classList.add("active"),activeTypeFilter=e.target.getAttribute("data-type"),renderAllWetlands())})}function renderMapHotspots(){const e=document.getElementById("map-hotspots-list");e&&WETLANDS_DATA.wetlands&&(e.innerHTML=WETLANDS_DATA.wetlands.map((e,t)=>`\n        <button class="map-spot-btn ${0===t?"active":""}" data-id="${e.id}">\n            <span class="spot-title">${e.name}</span>\n            <span class="spot-sub">📍 ${e.state} • ${e.type}</span>\n        </button>\n    `).join(""),showMapPreview(WETLANDS_DATA.wetlands[0]),e.addEventListener("click",e=>{const t=e.target.closest(".map-spot-btn");if(!t)return;const n=t.getAttribute("data-id"),a=WETLANDS_DATA.wetlands.find(e=>e.id===n);document.querySelectorAll(".map-spot-btn").forEach(e=>e.classList.remove("active")),t.classList.add("active"),a&&showMapPreview(a)}))}function showMapPreview(e){const t=document.getElementById("map-preview-card");t&&(t.innerHTML=`\n        <h3 style="margin: 0 0 0.5rem; color: #22d3ee; font-size: 1.5rem;">${e.name}</h3>\n        <div style="font-size: 0.85rem; color: #10b981; font-weight: 700; margin-bottom: 1rem;">${e.state} • Ramsar Site #${e.ramsarSiteNo} (${e.ramsarDeclared})</div>\n        <p style="color: var(--wetland-text-sub); line-height: 1.6; margin-bottom: 1.25rem;">${e.shortDesc}</p>\n        <div style="font-family: monospace; font-size: 0.85rem; color: #94a3b8; background: rgba(0,0,0,0.2); padding: 0.5rem 0.85rem; border-radius: 0.5rem; margin-bottom: 1.25rem;">Coordinates: ${e.coordinates.lat}° N, ${e.coordinates.lng}° E</div>\n        <a href="${e.exploreUrl}" class="btn-explore" style="display: inline-block; text-align: center;">Launch ${e.name} Explorer</a>\n    `)}function renderTrivia(){const e=document.getElementById("trivia-grid");e&&WETLANDS_DATA.didYouKnow&&(e.innerHTML=WETLANDS_DATA.didYouKnow.map(e=>`\n        <div class="trivia-card">\n            <h3>💡 ${e.title}</h3>\n            <p>${e.fact}</p>\n        </div>\n    `).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderStateFilterOptions(),renderTypeFilterPills(),renderFeaturedWetlands(),renderAllWetlands(),renderMapHotspots(),renderTrivia(),bindSearchAndFilters()});